<script>const shell=document.getElementById('app-shell'),toggle=document.getElementById('sidebar-toggle'),sideClose=document.getElementById('sidebar-close'),overlay=document.getElementById('sidebar-overlay');const mobile=()=>window.innerWidth<=960;if(!mobile()&&localStorage.getItem('surya-sidebar-collapsed')==='true')shell.classList.add('sidebar-collapsed');document.documentElement.classList.remove('surya-sidebar-precollapsed');toggle.onclick=()=>{if(mobile()){shell.classList.toggle('sidebar-open')}else{const collapsed=shell.classList.toggle('sidebar-collapsed');localStorage.setItem('surya-sidebar-collapsed',collapsed?'true':'false')}};const closeSide=()=>shell.classList.remove('sidebar-open');sideClose.onclick=closeSide;overlay.onclick=closeSide;window.addEventListener('resize',()=>{if(!mobile())shell.classList.remove('sidebar-open')});
const numberRender=(value,type)=>type==='display'?(value===null||value===''?'–':new Intl.NumberFormat('id-ID').format(Number(value))):value;const percentRender=(value,type)=>{if(type!=='display')return value;if(value===null||value==='')return '–';const n=Number(value);return `${n>0?'+':''}${new Intl.NumberFormat('id-ID',{minimumFractionDigits:1,maximumFractionDigits:1}).format(n)}%`};const baseColumns=['id_outlet','nama_outlet','kecamatan','sf','tap','pjp'].map(data=>({data,defaultContent:'-'}));const metricColumns=[];['st_sa','st_pv','cvm','super_seru','comsak','hot_promo'].forEach(metric=>{['fm1','m1','mtd','gap','mom_pct'].forEach((period,index)=>{const unavailable=metric.startsWith('st_')&&period!=='mtd';metricColumns.push({data:`${metric}_${period}`,defaultContent:null,orderable:!unavailable,className:`metric ${index===0?'group-start ':''}${metric.startsWith('st_')?'sales':'upload'} ${period==='mom_pct'?'mom-value':''}`,render:period==='mom_pct'?percentRender:numberRender})})});const table=$('table').DataTable({processing:true,serverSide:true,searchDelay:400,pageLength:25,lengthMenu:[10,25,50,100],orderCellsTop:false,order:[[1,'asc']],dom:'rt<"dt-footer"lip>',ajax:{url:@json(route('surya.outlet-detail.data')),data:d=>{d.tap=document.getElementById('tap-filter').value}},columns:[...baseColumns,...metricColumns],language:{processing:'Memuat data...',emptyTable:'Outlet PJP tidak ditemukan',zeroRecords:'Data yang dicari tidak ditemukan',info:'Menampilkan _START_–_END_ dari _TOTAL_ outlet',infoEmpty:'Tidak ada data',lengthMenu:'Tampilkan _MENU_',paginate:{previous:'‹',next:'›'}}});table.on('draw',()=>{$('.mom-value').each(function(){const n=parseFloat(this.textContent.replace('%','').replace(',','.'));if(!Number.isNaN(n))this.classList.add(n>=0?'positive':'negative')})});const apply=()=>table.search(document.getElementById('outlet-search').value).ajax.reload();document.getElementById('apply-filter').onclick=apply;document.getElementById('tap-filter').onchange=()=>table.ajax.reload();document.getElementById('outlet-search').addEventListener('keydown',e=>{if(e.key==='Enter')apply()});</script>
